def run_validator(root: Path) -> str:
    validator_path = root / "packet-snapshot/candidate-artifacts/validate_root_deployment_packet.py"
    completed = subprocess.run(
        [str(repo_root / ".venv/bin/python"), "-B", str(validator_path), str(root)],
        cwd=validator_path.parent,
        env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"},
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
    )
    text = completed.stdout.decode()
    require(completed.returncode == 0, "VALIDATOR_NONZERO\n" + text)
    require("VALIDATION=PASS" in text, "VALIDATOR_MARKER")
    return text

def run_negative(root: Path) -> str:
    test_path = root / "packet-snapshot/candidate-artifacts/test_root_deployment_packet_negative.py"
