        cwd=test_path.parent,
        env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"},
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
    )
    text = completed.stdout.decode()
    require(completed.returncode == 0, "NEGATIVE_NONZERO\n" + text)
    require("Ran 21 tests" in text, "NEGATIVE_COUNT")
    require([line.strip() for line in text.splitlines()].count("OK") == 1, "NEGATIVE_OK")
    return text

